<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>DSWD Walk-in Kiosk</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link href="https://fonts.googleapis.com/icon?family=Material+Icons" rel="stylesheet">
<style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#eef2f7;color:#111827;min-height:100vh}.screen{min-height:100vh;display:none}.screen.active{display:flex}.start-screen{align-items:center;justify-content:center;padding:30px;background:linear-gradient(135deg,#0b2e83,#168fcb)}.start-card{width:820px;max-width:96%;background:#fff;border-radius:28px;padding:48px 38px;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,.28)}.logo-circle{width:116px;height:116px;border-radius:50%;margin:0 auto 20px;display:flex;align-items:center;justify-content:center;background:#eff6ff;color:#0b2e83}.logo-circle .material-icons{font-size:64px}.start-card h1{margin:0;font-size:42px;color:#00008b}.start-card p{margin:14px auto 22px;font-size:18px;color:#374151;line-height:1.5;max-width:650px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:22px 0}.step{background:#f8fafc;border:1px solid #e5e7eb;border-radius:14px;padding:14px}.step b{display:block;color:#0b2e83;margin-bottom:4px}.tap-btn{border:none;border-radius:999px;background:#0b2e83;color:#fff;font-size:24px;font-weight:900;padding:20px 48px;cursor:pointer;box-shadow:0 12px 26px rgba(11,46,131,.28)}.form-screen{align-items:stretch;justify-content:center;padding:24px}.kiosk-shell{width:1180px;max-width:100%;display:flex;flex-direction:column;min-height:calc(100vh - 48px)}.topbar{background:#0b2e83;color:white;padding:18px 22px;border-radius:18px 18px 0 0;display:flex;align-items:center;justify-content:space-between;gap:14px}.topbar h1{margin:0;font-size:26px}.topbar p{margin:4px 0 0;opacity:.9;font-size:14px}.home-btn{border:none;border-radius:10px;background:rgba(255,255,255,.16);color:white;padding:12px 16px;font-weight:900;cursor:pointer;display:inline-flex;align-items:center;gap:6px}.form-card{background:#fff;border:1px solid #d6dce8;border-top:0;border-radius:0 0 18px 18px;padding:22px;flex:1;overflow:auto}.helper-note{background:#eff6ff;border:1px solid #bfdbfe;color:#1e40af;padding:14px 16px;border-radius:12px;font-size:15px;font-weight:800;margin-bottom:18px}.prio-note{background:#fff7ed;border-color:#fed7aa;color:#9a3412}.address-note{background:#ecfeff;border-color:#a5f3fc;color:#155e75}.section-title{margin:20px 0 14px;color:#0f2f56;display:flex;align-items:center;gap:8px;font-size:19px}.section-title:first-of-type{margin-top:0}.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.field-group{display:flex;flex-direction:column}.field-group label{font-size:14px;font-weight:900;color:#374151;margin-bottom:7px}.optional{font-size:12px;color:#64748b;font-weight:800}.field-group input,.field-group select{height:50px;padding:0 14px;border:1px solid #cbd5e1;border-radius:10px;font-size:16px;background:white;outline:none;width:100%}.field-group input:focus,.field-group select:focus{border-color:#168fcb;box-shadow:0 0 0 3px rgba(22,143,203,.12)}.field-group select:disabled{background:#f1f5f9;color:#64748b}.two{grid-column:span 2}.full{grid-column:1/-1}.actions{display:flex;gap:12px;margin-top:24px;flex-wrap:wrap}.submit-btn,.clear-btn{min-height:54px;border:none;border-radius:12px;padding:0 24px;font-size:16px;font-weight:900;cursor:pointer;display:inline-flex;align-items:center;gap:8px}.submit-btn{background:#168fcb;color:white}.clear-btn{background:#e5e7eb;color:#111827}.success-screen{align-items:center;justify-content:center;padding:30px;background:#f3f6fb}.success-card{width:720px;max-width:96%;background:white;border-radius:24px;padding:44px 34px;text-align:center;border:1px solid #d6dce8;box-shadow:0 14px 35px rgba(15,23,42,.14)}.success-icon{width:105px;height:105px;border-radius:50%;background:#dcfce7;color:#166534;display:flex;align-items:center;justify-content:center;margin:0 auto 20px}.success-icon .material-icons{font-size:60px}.success-card h1{margin:0;color:#166534;font-size:34px}.success-card p{color:#374151;font-size:17px;line-height:1.5}.code-box,.queue-box{background:#eff6ff;color:#00008b;border:1px solid #bfdbfe;padding:14px 18px;border-radius:12px;font-size:24px;font-weight:900;margin:10px auto;display:inline-block}.queue-box.prio{background:#fff7ed;color:#c2410c;border-color:#fed7aa}.done-btn{border:none;border-radius:999px;background:#0b2e83;color:white;font-size:18px;font-weight:900;padding:16px 34px;cursor:pointer}.address-preview{min-height:50px;display:flex;align-items:center;padding:12px 14px;border:1px solid #bae6fd;background:#f0f9ff;border-radius:10px;font-size:15px;font-weight:800;color:#155e75}.loading-small{font-size:12px;color:#64748b;margin-top:5px;font-weight:800}@media(max-width:1000px){.form-grid,.steps{grid-template-columns:repeat(2,1fr)}.two{grid-column:span 1}.full{grid-column:1/-1}}@media(max-width:650px){.start-card h1{font-size:32px}.form-screen{padding:12px}.form-grid,.steps{grid-template-columns:1fr}.topbar{flex-direction:column;align-items:flex-start}}
</style>
</head>
<body>
<section id="startScreen" class="screen start-screen active"><div class="start-card"><div class="logo-circle"><span class="material-icons">how_to_reg</span></div><h1>DSWD Walk-in Registration</h1><p>Good day. Please register here first before proceeding inside. The guard/staff will use your record to verify your queue and direct you to assessment.</p><div class="steps"><div class="step"><b>1. Register</b>Enter your basic details.</div><div class="step"><b>2. Get Queue</b>PWD, pregnant, and seniors are priority.</div><div class="step"><b>3. Wait for Call</b>Proceed when your queue is called.</div></div><button class="tap-btn" onclick="showForm()">Tap to Register</button></div></section>
<section id="formScreen" class="screen form-screen"><div class="kiosk-shell"><div class="topbar"><div><h1>Guard Walk-in Registration</h1><p>Client-facing form for fast intake before verification.</p></div><button class="home-btn" type="button" onclick="goHome()"><span class="material-icons">home</span> Home</button></div>
<form action="../api/add_walkin.php" method="POST" class="form-card" onsubmit="return prepareBirthday()"><input type="hidden" name="source" value="kiosk"><input type="hidden" name="birthday_month" id="birthdayMonth"><input type="hidden" name="birthday_day" id="birthdayDay"><input type="hidden" name="birthday_year" id="birthdayYear"><div class="helper-note">After submission, the system automatically creates your queue number. PWD, pregnant clients, and seniors are marked priority.</div><div class="helper-note prio-note" id="priorityPreview" style="display:none;">Priority queue preview: PRIO will be generated.</div>
<h3 class="section-title"><span class="material-icons">person</span>Personal Information</h3><div class="form-grid">
<div class="field-group"><label>Last Name *</label><input type="text" name="last_name" required autocomplete="off"></div><div class="field-group"><label>First Name *</label><input type="text" name="first_name" required autocomplete="off"></div><div class="field-group"><label>Middle Name</label><input type="text" name="middle_name" autocomplete="off"></div><div class="field-group"><label>Ext. Name <span class="optional">Optional</span></label><input type="text" name="ext_name" placeholder="Jr., Sr., III" autocomplete="off"></div>
<div class="field-group"><label>Birthday *</label><input type="text" id="birthdayInput" placeholder="MM/DD/YYYY" maxlength="10" required autocomplete="off"></div><div class="field-group"><label>Age *</label><input type="number" name="age" id="ageInput" min="0" max="130" required readonly></div><div class="field-group"><label>Sex *</label><select name="sex" id="sexSelect" required><option value="">Select</option><option value="Male">Male</option><option value="Female">Female</option></select></div><div class="field-group"><label>PWD? *</label><select name="sms_opt_in" id="pwdSelect" required><option value="0">No</option><option value="1">Yes - Priority</option></select></div>
<div class="field-group" id="pregnantGroup"><label>Pregnant? *</label><select name="is_pregnant" id="pregnantSelect" required><option value="0">No</option><option value="1">Yes - Priority</option></select></div><div class="field-group"><label>Contact Number</label><input type="text" name="contact_number" placeholder="09XXXXXXXXX" autocomplete="off"></div><div class="field-group"><label>ID Presented</label><select name="national_id"><option value="None">None</option><option value="PhilSys ID">PhilSys ID</option><option value="Senior Citizen ID">Senior Citizen ID</option><option value="PWD ID">PWD ID</option><option value="Barangay Certificate">Barangay Certificate</option><option value="Other ID">Other ID</option></select></div><div class="field-group"><label>Household ID</label><input type="text" name="household_id" autocomplete="off"></div>
<div class="field-group"><label>Assistance Type *</label><select name="program_type" required><option value="AICS">AICS</option><option value="AKAP">AKAP</option><option value="Emergency Assistance">Emergency Assistance</option><option value="Medical Assistance">Medical Assistance</option><option value="Educational Assistance">Educational Assistance</option><option value="Other">Other</option></select></div>
</div>
<h3 class="section-title"><span class="material-icons">location_on</span>Address</h3><div class="helper-note address-note" id="addressStatus">Loading complete Philippine address list from PSGC...</div><div class="form-grid">
<div class="field-group"><label>Region *</label><select name="region" id="regionSelect" required disabled><option value="">Loading regions...</option></select><div class="loading-small" id="regionHint"></div></div>
<div class="field-group"><label>Province *</label><select name="province" id="provinceSelect" required disabled><option value="">Select region first</option></select><div class="loading-small" id="provinceHint"></div></div>
<div class="field-group"><label>City / Municipality *</label><select name="city_municipality" id="citySelect" required disabled><option value="">Select province first</option></select><div class="loading-small" id="cityHint"></div></div>
<div class="field-group"><label>Barangay *</label><select name="barangay" id="barangaySelect" required disabled><option value="">Select city first</option></select><div class="loading-small" id="barangayHint"></div></div>
<div class="field-group two"><label>LGU *</label><input type="text" name="lgu" id="lguInput" readonly required></div><div class="field-group two"><label>Complete Address Preview</label><div class="address-preview" id="addressPreview">Select your address.</div></div>
</div><div class="actions"><button type="submit" class="submit-btn"><span class="material-icons">confirmation_number</span> Submit and Get Queue</button><button type="reset" class="clear-btn"><span class="material-icons">backspace</span> Clear Form</button></div></form></div></section>
<section id="successScreen" class="screen success-screen"><div class="success-card"><div class="success-icon"><span class="material-icons">check_circle</span></div><h1>Registration Complete</h1><p>Your record and queue number are now saved. Please show this screen to the guard or wait for your queue to be called.</p><div>Beneficiary Code</div><div class="code-box" id="codeBox">Saved</div><br><div>Queue Number</div><div class="queue-box" id="queueBox">Pending</div><br><button class="done-btn" onclick="goHome()">Done</button></div></section>
<script>
const PSGC='https://psgc.gitlab.io/api';
const regionSelect=document.getElementById('regionSelect'),provinceSelect=document.getElementById('provinceSelect'),citySelect=document.getElementById('citySelect'),barangaySelect=document.getElementById('barangaySelect'),lguInput=document.getElementById('lguInput'),birthdayInput=document.getElementById('birthdayInput'),ageInput=document.getElementById('ageInput'),pwdSelect=document.getElementById('pwdSelect'),pregnantSelect=document.getElementById('pregnantSelect'),sexSelect=document.getElementById('sexSelect'),priorityPreview=document.getElementById('priorityPreview'),addressStatus=document.getElementById('addressStatus'),addressPreview=document.getElementById('addressPreview');
const regionHint=document.getElementById('regionHint'),provinceHint=document.getElementById('provinceHint'),cityHint=document.getElementById('cityHint'),barangayHint=document.getElementById('barangayHint');
let selectedRegionCode='',selectedProvinceCode='',selectedCityCode='',independentRegionMode=false;
function setStatus(text,bad=false){addressStatus.textContent=text;addressStatus.style.background=bad?'#fef2f2':'#ecfeff';addressStatus.style.borderColor=bad?'#fecaca':'#a5f3fc';addressStatus.style.color=bad?'#991b1b':'#155e75'}
function sortByName(a,b){return String(a.name).localeCompare(String(b.name))}
function fillSelect(select,items,placeholder){select.innerHTML='<option value="">'+placeholder+'</option>';items.sort(sortByName).forEach(item=>{const opt=document.createElement('option');opt.value=item.name;opt.textContent=item.name;opt.dataset.code=item.code||'';select.appendChild(opt)});select.disabled=false}
function resetSelect(select,placeholder){select.innerHTML='<option value="">'+placeholder+'</option>';select.disabled=true}
async function getJSON(url){const res=await fetch(url,{cache:'force-cache'});if(!res.ok)throw new Error('PSGC request failed');return await res.json()}
async function initPlaces(){try{setStatus('Loading all Philippine regions...');resetSelect(provinceSelect,'Select region first');resetSelect(citySelect,'Select province first');resetSelect(barangaySelect,'Select city first');const regions=await getJSON(PSGC+'/regions/');fillSelect(regionSelect,regions,'Select Region');regionHint.textContent=regions.length+' regions loaded';setStatus('Complete Philippine address dropdown loaded. Select Region → Province → City/Municipality → Barangay.')}catch(e){setStatus('Unable to load PSGC address list. Check internet connection, then refresh this page.',true)}}
async function updateProvinces(){selectedRegionCode=regionSelect.selectedOptions[0]?.dataset.code||'';selectedProvinceCode='';selectedCityCode='';independentRegionMode=false;lguInput.value='';updateAddressPreview();resetSelect(provinceSelect,'Loading provinces...');resetSelect(citySelect,'Select province first');resetSelect(barangaySelect,'Select city first');provinceHint.textContent='';cityHint.textContent='';barangayHint.textContent='';if(!selectedRegionCode){resetSelect(provinceSelect,'Select region first');return}try{const provinces=await getJSON(PSGC+'/regions/'+selectedRegionCode+'/provinces/');const cities=await getJSON(PSGC+'/regions/'+selectedRegionCode+'/cities-municipalities/');const items=provinces.map(p=>({name:p.name,code:p.code}));items.push({name:'Independent City / No Province',code:'REGION_CITIES'});fillSelect(provinceSelect,items,'Select Province');provinceHint.textContent=provinces.length+' provinces + independent city option';if(provinces.length===0){provinceSelect.value='Independent City / No Province';provinceSelect.selectedOptions[0].dataset.code='REGION_CITIES';updateCities()}}catch(e){setStatus('Failed to load provinces. Please refresh.',true)}}
async function updateCities(){selectedProvinceCode=provinceSelect.selectedOptions[0]?.dataset.code||'';selectedCityCode='';independentRegionMode=selectedProvinceCode==='REGION_CITIES';lguInput.value='';updateAddressPreview();resetSelect(citySelect,'Loading cities/municipalities...');resetSelect(barangaySelect,'Select city first');cityHint.textContent='';barangayHint.textContent='';if(!selectedProvinceCode){resetSelect(citySelect,'Select province first');return}try{const url=independentRegionMode?PSGC+'/regions/'+selectedRegionCode+'/cities-municipalities/':PSGC+'/provinces/'+selectedProvinceCode+'/cities-municipalities/';const cities=await getJSON(url);fillSelect(citySelect,cities,'Select City / Municipality');cityHint.textContent=cities.length+' cities/municipalities loaded'}catch(e){setStatus('Failed to load cities/municipalities. Please refresh.',true)}}
async function updateBarangays(){selectedCityCode=citySelect.selectedOptions[0]?.dataset.code||'';lguInput.value=citySelect.value||'';updateAddressPreview();resetSelect(barangaySelect,'Loading barangays...');barangayHint.textContent='';if(!selectedCityCode){resetSelect(barangaySelect,'Select city first');return}try{const barangays=await getJSON(PSGC+'/cities-municipalities/'+selectedCityCode+'/barangays/');fillSelect(barangaySelect,barangays,'Select Barangay');barangayHint.textContent=barangays.length+' barangays loaded'}catch(e){setStatus('Failed to load barangays. Please refresh.',true)}}
function updateAddressPreview(){const brgy=barangaySelect.value,city=citySelect.value,province=provinceSelect.value==='Independent City / No Province'?'':provinceSelect.value,region=regionSelect.value;const parts=[brgy,city,province,region].filter(Boolean);addressPreview.textContent=parts.length?parts.join(', '):'Select your address.';lguInput.value=city||''}
regionSelect.addEventListener('change',updateProvinces);provinceSelect.addEventListener('change',updateCities);citySelect.addEventListener('change',updateBarangays);barangaySelect.addEventListener('change',updateAddressPreview);initPlaces();
function updatePriority(){const age=parseInt(ageInput.value||'0',10);if(sexSelect.value!=='Female')pregnantSelect.value='0';pregnantSelect.disabled=sexSelect.value!=='Female';priorityPreview.style.display=(pwdSelect.value==='1'||pregnantSelect.value==='1'||age>=60)?'block':'none'}pwdSelect.addEventListener('change',updatePriority);pregnantSelect.addEventListener('change',updatePriority);sexSelect.addEventListener('change',updatePriority);
birthdayInput.addEventListener('input',function(){let v=this.value.replace(/\D/g,'').slice(0,8);if(v.length>=5)v=v.slice(0,2)+'/'+v.slice(2,4)+'/'+v.slice(4);else if(v.length>=3)v=v.slice(0,2)+'/'+v.slice(2);this.value=v;autoAge();updatePriority()});function autoAge(){const p=birthdayInput.value.split('/');if(p.length!==3||p[2].length!==4)return;const m=parseInt(p[0],10),d=parseInt(p[1],10),y=parseInt(p[2],10);const b=new Date(y,m-1,d);if(isNaN(b.getTime()))return;const t=new Date();let age=t.getFullYear()-b.getFullYear();const mo=t.getMonth()-b.getMonth();if(mo<0||(mo===0&&t.getDate()<b.getDate()))age--;if(age>=0&&age<=130)ageInput.value=age}
function prepareBirthday(){const p=birthdayInput.value.split('/');if(p.length!==3)return false;const m=parseInt(p[0],10),d=parseInt(p[1],10),y=parseInt(p[2],10);if(!m||!d||!y||m<1||m>12||d<1||d>31||y<1900)return false;document.getElementById('birthdayMonth').value=m;document.getElementById('birthdayDay').value=d;document.getElementById('birthdayYear').value=y;return true}
function showOnly(id){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.getElementById(id).classList.add('active')}function showForm(){showOnly('formScreen');updatePriority()}function goHome(){document.querySelector('form').reset();priorityPreview.style.display='none';updatePriority();resetSelect(provinceSelect,'Select region first');resetSelect(citySelect,'Select province first');resetSelect(barangaySelect,'Select city first');lguInput.value='';addressPreview.textContent='Select your address.';showOnly('startScreen')}const params=new URLSearchParams(window.location.search);if(params.get('success')==='1'){const code=params.get('code')||'Saved',queue=params.get('queue')||'Pending',type=params.get('type')||'';document.getElementById('codeBox').innerText=code;const qb=document.getElementById('queueBox');qb.innerText=queue;if(type==='priority')qb.classList.add('prio');showOnly('successScreen');window.history.replaceState({},document.title,'index.php')}updatePriority();
</script>
</body>
</html>